const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=()=>({bridges:[{id:'a',name:'Conference Alpha',state:'established',establishedAt:'13:31',transport:'X-band'},{id:'b',name:'Conference Bravo',state:'preparing',transport:'KA commercial'}],calls:[{id:'a',name:'Customer Alpha',bridge:'a',startDate:'2026-10-28',endDate:'2026-10-28',start:'13:35',end:'14:10',state:'active',connected:true},{id:'b',name:'Customer Bravo',bridge:'b',startDate:'2026-10-28',endDate:'2026-10-28',start:'13:55',end:'14:25',state:'scheduled',connected:false}],issues:[],notes:[],transport:{Voice:'X-band',VTC:'KA commercial',Data:'Starshield'},transportNames:['KA commercial','X-band','Starshield'],outages:[{transport:'KA commercial',start:'13:50',end:'14:10'}],history:[{time:'13:35',text:'Customer Alpha call started and customer joined.',detail:'Conference Alpha remains independently established'},{time:'13:31',text:'Conference Alpha established after successful two-way distant-end test.',detail:'Human-reported observation'}]});
let state;try{state=JSON.parse(localStorage.getItem('operator-design-v3'))||initial()}catch{state=initial()}// Rename the integrated transport in existing demo data without resetting IDs or operator edits.
const renameTransport=value=>typeof value==='string'?value.replace(/Starlink/g,'Starshield'):value;
state.bridges.forEach(b=>b.transport=renameTransport(b.transport));
Object.keys(state.transport).forEach(k=>state.transport[k]=renameTransport(state.transport[k]));
state.transportNames=state.transportNames.map(renameTransport);
state.outages.forEach(o=>o.transport=renameTransport(o.transport));
state.history.forEach(h=>{h.text=renameTransport(h.text);h.detail=renameTransport(h.detail)});
state.calls.forEach(c=>{c.startDate??='2026-10-28';c.endDate??='2026-10-28'});state.history.forEach(h=>{h.text=h.text.replace(/UTC/g,'Zulu');h.detail=h.detail.replace(/UTC/g,'Zulu')});localStorage.setItem('operator-design-v3',JSON.stringify(state));
let page='Operations',focused=null,callDraft=null,noteDraft='',simulateFailure=false;
function save(){localStorage.setItem('operator-design-v3',JSON.stringify(state))}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}function log(text,detail='Training 07 · Leg 1 · demo observation',time='13:42'){state.history.unshift({time,text,detail});save()}function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}function closeModal(){$('#modal').close()}function resetDemo(){if(!confirm('Reset fictional data and discard demo changes?'))return;state=initial();callDraft=null;save();page='Operations';render();toast('Demo reset. No real records were changed.')}function bridge(id){return state.bridges.find(x=>x.id===id)}function call(id){return state.calls.find(x=>x.id===id)}function minus10(t){let [h,m]=t.split(':').map(Number);return `${String(Math.floor((h*60+m-10+1440)%1440/60)).padStart(2,'0')}:${String((m-10+60)%60).padStart(2,'0')}`}
function go(p,id){page=p;focused=id||null;render();if(id)setTimeout(()=>document.getElementById('record-'+id)?.scrollIntoView({behavior:'smooth',block:'center'}),30)}
function renderTimeline(){let events=[{t:'14:00',title:'Scheduled departure',sub:'Training 07 · Leg 1',action:"showDeparture()"},{t:'14:20',title:'Predicted Starshield PoP transition',sub:'Prediction only · not a known outage',action:"go('Transport')"},{t:'15:30',title:'Scheduled arrival',sub:'Training 07 · Leg 1',action:"showDeparture()"}];state.calls.filter(c=>!['cancelled','completed'].includes(c.state)).forEach(c=>{if(c.state==='scheduled'){events.push({t:prep(c).time,date:prep(c).date,title:((c.bridge==='direct'?c.established:bridge(c.bridge)?.state==='established')?'Ready: ':'Prepare ')+c.name,sub:(c.bridge==='direct'?'Direct point-to-point':bridge(c.bridge)?.name||'No conference')+' · open next step',action:`go('Operations','call-${c.id}')`});events.push({t:c.start,date:c.startDate,title:c.name+' starts',sub:c.bridge==='direct'?'Direct point-to-point':bridge(c.bridge)?.name||'Choose a conference',action:`go('Operations','call-${c.id}')`})}if(c.end)events.push({t:c.end,date:c.endDate,title:c.name+' ends',sub:'Scheduled · completion is reported manually',action:`go('Operations','call-${c.id}')`})});state.issues.filter(i=>i.status!=='Resolved').forEach(i=>events.push({t:'—',title:'Follow up: '+i.title,sub:'Unscheduled · open issue',action:`go('Issues','issue-${i.id}')`}));state.outages.forEach(o=>events.push({t:o.start,title:o.transport+' scheduled outage',sub:o.start+'–'+o.end+' Zulu · advisory only',action:"go('Transport')"}));events.sort((a,b)=>a.t==='—'?1:b.t==='—'?-1:((a.date||'2026-10-28')+'T'+a.t).localeCompare((b.date||'2026-10-28')+'T'+b.t));$('#timeline').innerHTML=events.map(e=>`<button class="event" onclick="${e.action}"><time>${e.t}${e.date&&e.date!=='2026-10-28'?'<small>'+e.date+'</small>':''}</time><div><strong>${esc(e.title)}</strong><small>${esc(e.sub)}</small></div></button>`).join('')}
function render(){renderTimeline();$('#nav').innerHTML=['Operations','Transport','Issues','Notes','History'].map(p=>`<button class="${p===page?'active':''}" onclick="go('${p}')">${p}${p==='Issues'&&state.issues.some(i=>i.status!=='Resolved')?' · '+state.issues.filter(i=>i.status!=='Resolved').length:''}</button>`).join('');$('#pageTitle').textContent=page;$('#pageDesc').textContent={Operations:'Keep the mission in view. Work the next action.',Transport:'Report the transport actually in use. These controls do not route hardware.',Issues:'Capture the problem, then keep its status current.',Notes:'Write it down. The time starts at now; change it only when needed.',History:'What happened, when it happened, and what changed.'}[page];$('#content').innerHTML=({Operations:renderOps,Transport:renderTransport,Issues:renderIssues,Notes:renderNotes,History:renderHistory}[page])()}
function renderOps(){let next=state.calls.find(c=>c.state==='scheduled');return `${next?`<div class="banner"><span class="icon">◷</span><div><strong>Next up: ${(next.bridge==='direct'?next.established:bridge(next.bridge)?.state==='established')?'ready for':'prepare'} ${esc(next.name)}</strong><p>${prep(next).date} ${prep(next).time} Zulu preparation · ${next.startDate} ${next.start} Zulu start</p></div><button onclick="go('Operations','call-${next.id}')">Open next step →</button></div>`:''}<div class="lanes"><section><div class="lane-head"><h2>Conferences</h2><button class="subtle" onclick="openBridge()">＋ New conference</button></div>${state.bridges.map(renderBridge).join('')}<p class="hint">Conferences are reusable. Finishing a call does not close its conference.</p></section><section><div class="lane-head"><h2>Calls <span>· ${state.calls.filter(c=>!['cancelled','completed'].includes(c.state)).length} current</span></h2><span>Active & upcoming</span></div>${state.calls.filter(c=>!['cancelled','completed'].includes(c.state)).map(renderCall).join('')||'<div class="empty">No active or scheduled calls.</div>'}<p class="hint">Established means the distant end can hear us and we can hear them. Connect the customer afterward—no separate test step.</p></section></div><p class="proposal">DESIGN PROPOSAL · Now and Communications become one Operations workspace. Timeline and context remain available in every view.</p>`}
function renderBridge(b){const active=state.calls.some(c=>c.bridge===b.id&&c.state==='active');const connected=state.calls.filter(c=>c.bridge===b.id&&c.connected).length;const open=b.state!=='closed';const canClose=open&&!active&&!connected;const established=b.state==='established';const action=established?`<button class="primary conference-toggle" ${canClose?'':'disabled'} onclick="bridgeAction('${b.id}','close')">Close conference</button>`:`<button class="primary conference-toggle" onclick="bridgeAction('${b.id}','establish')">${b.state==='interrupted'?'Reestablish':'Report established'}</button>`;return `<article class="card conference-card ${focused==='bridge-'+b.id?'focus':''}" id="record-bridge-${b.id}"><div class="card-top"><div><h3>${esc(b.name)}</h3><div class="meta">Reusable conference · ${esc(b.transport)}</div></div><span class="pill ${established?'':'amber'}">${b.state.toUpperCase()}</span></div><div class="conference-advisory">${conferenceAdvisory(b)}</div><div class="facts"><div>Two-way distant-end check<b>${established?'Complete · '+(b.establishedAt||'13:42')+' Zulu':'Included in establishment'}</b></div><div>Customers connected<b>${connected}</b></div></div><p class="conference-status soft">${established?(active||connected?'Call or customer active · close available when idle.':'Established · ready for a call. Close when no longer needed.'):'Report established once the distant end can hear us and we can hear them.'}</p><div class="actions conference-actions">${action}<details><summary aria-label="Conference actions">•••</summary><div class="menu"><button onclick="openConferenceTransport('${b.id}')">Assign transport</button><button onclick="bridgeAction('${b.id}','interrupt')">Report interruption</button><button onclick="go('History')">View history</button></div></details></div></article>`}

function renderCall(c){let b=bridge(c.bridge),next;if(c.bridge==='direct'&&!c.established)next=`<button class="primary" onclick="callAction('${c.id}','establish')">Report direct call established</button>`;else if(!b&&c.bridge!=='direct')next=`<button class="primary" onclick="openCall('${c.id}')">Choose conference</button>`;else if(b&&b.state!=='established')next=`<button class="primary" onclick="bridgeAction('${b.id}','establish')">Report conference established</button>`;else if(c.state!=='active')next=`<button class="primary" onclick="callAction('${c.id}','start')">Report call started</button>`;else if(!c.connected)next=`<button class="primary" onclick="callAction('${c.id}','connect')">Report customer connected</button>`;else next=`<button onclick="callAction('${c.id}','leave')">Report customer left</button>`;return `<article class="card ${focused==='call-'+c.id?'focus':''}" id="record-call-${c.id}"><div class="card-top"><div><h3>${esc(c.name)}</h3><div class="meta">${scheduleText(c)} · Voice<br>${esc(c.bridge==='direct'?'Direct point-to-point':b?.name||'No conference selected')}</div></div><span class="pill ${c.state==='active'?'':'gray'}">${c.state==='active'?'IN PROGRESS':'SCHEDULED'}</span></div>${callAdvisory(c)}<div class="steps"><span class="${(c.bridge==='direct'?c.established:b?.state==='established')?'done':''}">${(c.bridge==='direct'?c.established:b?.state==='established')?'✓':'○'} Established</span><span class="${c.connected?'done':''}">${c.connected?'✓':'○'} Connected</span></div><div class="actions">${next}${c.state==='active'&&!c.connected?`<button onclick="callAction('${c.id}','finish')">Finish call</button>`:''}<details><summary aria-label="Call actions">•••</summary><div class="menu"><button onclick="openCall('${c.id}')">Edit / reschedule</button>${c.state==='scheduled'?`<button class="danger" onclick="cancelCall('${c.id}')">Cancel call</button>`:''}<button onclick="go('History')">View history</button></div></details></div></article>`}
function bridgeAction(id,a){let b=bridge(id);if(a==='close'){if(b.state==='closed')return;if(state.calls.some(c=>c.bridge===id&&(c.state==='active'||c.connected)))return toast('Finish active calls and report remaining customers left before closing.');}if(a==='establish'){b.state='established';b.establishedAt='13:42'}if(a==='interrupt'){b.state='interrupted';b.establishedAt=null}if(a==='close'){b.state='closed';b.establishedAt=null}log(`${b.name}: ${a==='establish'?'established after successful two-way distant-end test':a==='interrupt'?'interruption reported':'closed'}.`);render();toast('Observation recorded. No hardware command was sent.')}
function callAction(id,a){let c=call(id);if(a==='establish'){c.established=true;log(c.name+': direct call established after successful two-way distant-end test.');}if(a==='start'){c.state='active';log(c.name+': actual start reported.')}if(a==='connect'){c.connected=true;log(c.name+': customer connected.')}if(a==='leave'){c.connected=false;log(c.name+': customer left.')}if(a==='finish'){if(c.connected)return toast('Report customer departure before finishing the call.');c.state='completed';log(c.name+': call completed.','Conference remains independently available')}render();toast('Call updated. Conference state is unchanged.')}
function cancelCall(id){const c=call(id);modal(`<h2>Cancel ${esc(c.name)}?</h2><p>This removes future preparation and start reminders. The call and cancellation remain in History.</p><div class="form-foot"><button onclick="closeModal()">Keep call</button><button class="danger" onclick="confirmCancel('${id}')">Cancel call</button></div>`)}function confirmCancel(id){let c=call(id);c.state='cancelled';log(c.name+': scheduled call cancelled.','Original schedule '+scheduleText(c)+' retained');closeModal();render();toast('Call cancelled. History retained.')}
function captureCall(){if($('#callName'))callDraft={...callDraft,name:$('#callName').value,start:readTime('callStart'),end:readTime('callEnd'),startDate:$('#callStartDate').value,endDate:$('#callEndDate').value,bridge:$('#callBridge').value,transport:$('#directTransport')?.value||callDraft.transport||''}}
function openCall(id){if(id){let c=call(id);callDraft={id:c.id,name:c.name,start:c.start,end:c.end,startDate:c.startDate,endDate:c.endDate,bridge:c.bridge,transport:c.transport||''}}else callDraft=callDraft||{name:'',start:'14:10',end:'14:35',startDate:'2026-10-28',endDate:'2026-10-28',bridge:''};drawCall()}
function drawCall(inline=false){let d=callDraft;modal(`<div class="context">TRAINING 07 / LEG 1 · Zulu</div><h2>${d.id?'Edit / reschedule call':'Schedule a call'}</h2><p>Choose an existing conference, create one here, or use a direct point-to-point connection.</p><label for="callName">Customer / call name</label><input id="callName" value="${esc(d.name)}" placeholder="e.g. Customer Charlie"><div class="form-grid"><div><label for="callStartDate">Start date · Zulu</label><input id="callStartDate" type="date" value="${d.startDate}">${timeControls("callStart",d.start,"Start")}</div><div><label for="callEndDate">End date · Zulu</label><input id="callEndDate" type="date" value="${d.endDate}">${timeControls("callEnd",d.end,"End")}</div></div><label for="callBridge">Connection</label><select id="callBridge" onchange="captureCall();drawCall()"><option value="">Choose conference or direct</option><option value="direct" ${d.bridge==='direct'?'selected':''}>Direct point-to-point · no conference</option>${state.bridges.map(b=>`<option value="${b.id}" ${d.bridge===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select>${d.bridge==='direct'?`<label for="directTransport">Transport · optional</label><select id="directTransport"><option value="">Unknown / not specified</option>${state.transportNames.map(t=>`<option ${d.transport===t?'selected':''}>${esc(t)}</option>`).join('')}</select><p class="soft">No conference is needed. Establishment includes the two-way distant-end check before connecting the customer.</p>`:''}${inline?`<div class="inline"><label for="newBridgeName">New reusable conference</label><input id="newBridgeName" placeholder="Conference Charlie"><p class="soft">Creating it does not establish it. Establishment includes the two-way distant-end test.</p><div class="actions"><button onclick="captureCall();drawCall()">Back to call</button><button class="primary" onclick="saveInlineBridge()">Create & select</button></div></div>`:`<button class="subtle" onclick="captureCall();drawCall(true)">＋ Create a conference without leaving this call</button>`}<div class="error" id="formError"></div><div class="form-foot"><button onclick="captureCall();closeModal();toast('Call draft kept. Reopen Schedule call to continue.')">Keep draft & close</button><button class="primary" onclick="saveCall()">${d.id?'Save changes':'Schedule call'}</button></div>`)}
function saveInlineBridge(){captureCall();let name=$('#newBridgeName').value.trim();if(!name){$('#formError').textContent='Name the conference first.';return}let b={id:'b'+Date.now(),name,state:'preparing',transport:'Not configured'};state.bridges.push(b);callDraft.bridge=b.id;log(name+': conference created.','Independent reusable bridge · not established');drawCall();render();toast('Conference created and selected. Your call draft is intact.')}
function saveCall(){captureCall();let d=callDraft;if(!d.name.trim()||!d.start||!d.end||!d.bridge){$('#formError').textContent='Enter a name, start, end and a conference or direct connection.';return}if(!d.startDate||!d.endDate||d.endDate+'T'+d.end<=d.startDate+'T'+d.start){$('#formError').textContent='Choose an end date and time after the start, including the next date for an overnight call.';return}if(d.id){let c=call(d.id),old=scheduleText(c);Object.assign(c,d);log(c.name+': schedule updated.','Previous '+old+' → '+scheduleText(c))}else{state.calls.push({...d,id:'c'+Date.now(),state:'scheduled',connected:false});log(d.name+': call scheduled.','Planned '+scheduleText(d))}callDraft=null;closeModal();go('Operations');toast('Schedule saved. Timeline updated.')}
function openBridge(){modal(`<div class="context">TRAINING 07 / LEG 1</div><h2>New conference</h2><p>A reusable bridge, independent of any individual call.</p><label for="bridgeName">Conference name</label><input id="bridgeName" placeholder="Conference Charlie"><div class="error" id="formError"></div><div class="form-foot"><button onclick="closeModal()">Back</button><button class="primary" onclick="saveBridge()">Create conference</button></div>`)}function saveBridge(){let name=$('#bridgeName').value.trim();if(!name)return $('#formError').textContent='Enter a conference name.';state.bridges.push({id:'b'+Date.now(),name,state:'preparing',transport:'Not configured'});log(name+': conference created.');closeModal();render()}
function renderTransport(){return `<div class="list"><div class="banner"><div><strong>KA commercial · scheduled outage 13:50–14:10 Zulu</strong><p>${state.calls.filter(c=>(c.bridge==='direct'?c.transport:bridge(c.bridge)?.transport)==='KA commercial'&&overlaps(c,state.outages[0])).map(c=>esc(c.name)).join(', ')||'No current call'} overlapping this interval. Advisory only—no automatic switching or blocking.</p></div></div><div class="section-note">Current reported assignment · changing a selection does nothing until you explicitly report the change.</div>${Object.entries(state.transport).map(([service,t])=>`<article class="card row"><div><h3>${service}</h3><div class="meta">Reported transport <b style="color:var(--accent)">${t}</b></div></div><select class="transport-select" aria-label="${service} transport" id="transport-${service}">${[...state.transportNames,'Unavailable'].map(x=>`<option ${x===t?'selected':''}>${x}</option>`).join('')}</select><button onclick="reportTransport('${service}')">Report change</button></article>`).join('')}<button onclick="openAdHocTransport()">＋ Add ad hoc transport</button><p class="hint">Standard integrated transports: KA commercial, X-band and Starshield. Added transports have no integrated schedule coverage—not an indication of clear health.</p><p class="hint">This preserves the existing simple assignment path. Planned settings, historical records and audit detail stay out of the routine decision.</p><button class="subtle" onclick="go('History')">View assignment history →</button></div>`}function reportTransport(s){let next=$('#transport-'+s).value,old=state.transport[s];if(next===old)return toast('No change to report.');state.transport[s]=next;log(s+': reported transport changed to '+next+'.','Previous '+old+' · no hardware command sent');render();toast('Reported assignment updated.')}
function renderIssues(){return `<div class="list">${state.issues.length?state.issues.map(i=>`<article class="card ${focused==='issue-'+i.id?'focus':''}" id="record-issue-${i.id}"><div class="card-top"><div><h3>${esc(i.title)}</h3><div class="meta">${esc(i.context)} · reported ${i.time} Zulu</div></div><span class="pill ${i.status==='Resolved'?'':'amber'}">${i.status.toUpperCase()}</span></div><p>${esc(i.body)}</p><div class="actions">${i.status!=='Resolved'?`<button onclick="issueStatus('${i.id}','Monitoring')">Monitor</button><button class="primary" onclick="issueStatus('${i.id}','Resolved')">Resolve</button>`:''}<button class="subtle" onclick="go('History')">History</button></div></article>`).join(''):'<div class="empty"><h3>No open issues in this scenario</h3><p>Describe the problem first. Optional details can follow.</p><button onclick="openIssue()">＋ Log an issue</button></div>'}<p class="hint">No inferred impact graph. Reported issues do not silently change call or transport state.</p></div>`}function openIssue(){modal(`<div class="context">TRAINING 07 / LEG 1</div><h2>Log an issue</h2><label for="issueTitle">What is wrong?</label><input id="issueTitle" placeholder="Intermittent audio on Conference Bravo"><label for="issueBody">What should the next operator know?</label><textarea id="issueBody" placeholder="Observed symptoms and anything already tried"></textarea><label for="issueContext">Related to</label><select id="issueContext"><option>Current leg</option>${state.bridges.map(b=>`<option>${esc(b.name)}</option>`).join('')}<option>Transport</option></select><p class="soft">Reported now · 13:42 Zulu. Context can be changed before saving.</p><div class="error" id="formError"></div><div class="form-foot"><button onclick="closeModal()">Back</button><button class="primary" onclick="saveIssue()">Log issue</button></div>`)}function saveIssue(){let title=$('#issueTitle').value.trim();if(!title)return $('#formError').textContent='Describe the issue first.';state.issues.unshift({id:Date.now().toString(),title,body:$('#issueBody').value,context:$('#issueContext').value,status:'Open',time:'13:42'});log('Issue logged: '+title);closeModal();go('Issues');toast('Issue recorded. Other system states are unchanged.')}function issueStatus(id,s){let i=state.issues.find(i=>i.id===id);i.status=s;log(i.title+': '+s.toLowerCase()+'.');render()}
function renderNotes(){return `<div class="list">${state.notes.length?state.notes.map(n=>`<article class="card"><div class="meta">${esc(n.time.replace('T',' '))} Zulu · Training 07 / Leg 1</div><p style="color:var(--text);white-space:pre-wrap">${esc(n.text)}</p></article>`).join(''):'<div class="empty"><h3>A note, not a form</h3><p>Text and time. New notes start at Now; backdate when needed.</p><button onclick="openNote()">＋ Add note</button></div>'}<p class="hint">The entered occurrence time is accepted. Recorded-at audit time remains separate; existing historical precision is not rewritten.</p></div>`}function openNote(){modal(`<div class="context">TRAINING 07 / LEG 1</div><h2>Add a note</h2><label for="noteText">Note</label><textarea id="noteText" placeholder="What happened?">${esc(noteDraft)}</textarea><label for="noteDate">Occurred date · Zulu</label><input id="noteDate" type="date" value="2026-10-28">${timeControls('noteTime','13:42','Occurred')}<button onclick="$('#noteDate').value='2026-10-28';$('#noteTimeHour').value='13';$('#noteTimeMinute').value='42'">Now</button><p class="soft">Scenario clock is fixed at 13:42 Zulu. No precision selection required.</p><details><summary class="soft" style="cursor:pointer;margin-top:18px">Test save recovery</summary><p class="soft">Simulate one failed save. The note and its entered time remain available for retry.</p><button onclick="simulateFailure=true;toast('Next note save will simulate a failure.')">Fail the next save</button></details><div class="error" id="formError"></div><div class="form-foot"><button onclick="noteDraft=$('#noteText').value;closeModal()">Keep draft & close</button><button class="primary" onclick="saveNote()">Save note</button></div>`)}function saveNote(){let text=$('#noteText').value.trim(),time=$('#noteDate').value+'T'+readTime('noteTime');if(!text||!$('#noteDate').value)return $('#formError').textContent='Enter the note and its occurrence time.';if(simulateFailure){simulateFailure=false;$('#formError').textContent='Demo save failed. Your text and time are still here. Try Save note again.';return}state.notes.unshift({text,time});log('Note added: '+text,'Occurred '+time.replace('T',' ')+' Zulu · recorded at scenario time 13:42 Zulu');noteDraft='';closeModal();go('Notes');toast('Note saved.')}
function renderHistory(){return `<div class="list"><div class="section-note">All records in this fictional session · newest recorded first. Occurrence and recording time remain distinct.</div>${state.history.map(h=>`<div class="log"><time>${h.time} Zulu · RECORDED</time><p>${esc(h.text)}</p><small>${esc(h.detail)}</small></div>`).join('')}<p class="hint">Prototype scope: review-only history. A production design must retain corrections and existing audit provenance; it must also disclose any loaded-record search limits.</p></div>`}
function showDeparture(){modal(`<div class="context">TIMELINE / TRAINING 07</div><h2>Mission schedule</h2><p>Scheduled departure <b>14:00 Zulu</b><br>Scheduled arrival <b>15:30 Zulu</b></p><p>This is planned timing, not a report that departure occurred. The prototype keeps mission schedule detail in context instead of navigating away.</p><div class="form-foot"><button class="primary" onclick="closeModal()">Return to workspace</button></div>`)}
function showGuide(){modal(`<div class="context">DESIGN PROPOSAL · INTERACTIVE, FICTIONAL DATA</div><h2>One coherent operating flow</h2><p>Try the actions as an operator. Nothing connects to the real dashboard or changes hardware. Changes are saved only in this browser.</p><div class="guide-grid"><button onclick="closeModal();go('Operations','call-b')">1 · Prepare Bravo from the timeline<small>Establish the bridge after the two-way distant-end check succeeds. Then start the call and connect the customer. Alpha can remain active; there is no additional test step.</small></button><button onclick="closeModal();openCall()">2 · Schedule Charlie without leaving the form<small>Create its conference inline and preserve the draft—or choose Direct point-to-point without a conference.</small></button><button onclick="closeModal();openIssue()">3 · Review the KA outage, then report a problem or transport change<small>Bravo overlaps a known KA outage. Its call and conference show the interval. Add an ad hoc transport if needed; no schedule coverage is implied.</small></button><button onclick="closeModal();openNote()">4 · Capture a note at Now or an earlier time<small>Try the simulated failed save: your text and time should remain for retry.</small></button><button onclick="closeModal();go('Operations')">5 · Reschedule or cancel a scheduled call<small>Use the call’s ••• menu. Timeline updates; History retains the previous schedule.</small></button></div><p class="hint">Desktop: timeline plus parallel lanes. Phone: persistent horizontal timeline, same views and actions. Proposed Operations merges Now + Communications; not yet a product decision.</p><div class="form-foot"><button class="primary" onclick="closeModal()">Explore the workspace</button></div>`)}
const integratedTransports=['KA commercial','X-band','Starshield'];
function overlaps(c,o){return !['cancelled','completed'].includes(c.state)&&(c.startDate+'T'+c.start)<('2026-10-28T'+o.end)&&(c.endDate+'T'+c.end)>('2026-10-28T'+o.start)}
function callAdvisory(c){const b=c.bridge==='direct'?{transport:c.transport||'Unknown transport'}:bridge(c.bridge);if(!b)return '';if(!integratedTransports.includes(b.transport))return `<p class="hint">${esc(b.transport)} · no integrated outage schedule available. Health is unknown.</p>`;return state.outages.filter(o=>o.transport===b.transport&&overlaps(c,o)).map(o=>`<div class="outage"><strong>Scheduled ${esc(o.transport)} outage</strong><span>${o.start}–${o.end} Zulu overlaps ${esc(c.name)} (${c.start}–${c.end}).</span><small>Advisory only · choose what to do; no automatic switch.</small></div>`).join('')}
function conferenceAdvisory(b){if(!integratedTransports.includes(b.transport))return `<p class="hint">No integrated outage schedule for ${esc(b.transport)}. Health is unknown.</p>`;return state.outages.filter(o=>o.transport===b.transport).map(o=>{const affected=state.calls.filter(c=>c.bridge===b.id&&overlaps(c,o));return affected.length?`<div class="outage"><strong>Scheduled ${esc(o.transport)} outage · ${o.start}–${o.end} Zulu</strong><span>Affects ${affected.map(c=>esc(c.name)+' ('+c.start+'–'+c.end+')').join(', ')}.</span><small>Advisory only · conference assignment is unchanged.</small></div>`:''}).join('')}
function openConferenceTransport(id){const b=bridge(id);modal(`<div class="context">${esc(b.name)} · CONFERENCE ASSIGNMENT</div><h2>Assigned transport</h2><p>This changes the conference’s planned transport, not hardware routing.</p><label for="conferenceTransport">Transport</label><select id="conferenceTransport">${state.transportNames.map(t=>`<option ${t===b.transport?'selected':''}>${esc(t)}</option>`).join('')}</select><p class="hint">Ad hoc names can be added from Transport. They have no integrated outage schedule.</p><div class="form-foot"><button onclick="closeModal()">Back</button><button class="primary" onclick="saveConferenceTransport('${id}')">Save assignment</button></div>`)}
function saveConferenceTransport(id){const b=bridge(id),previous=b.transport;b.transport=$('#conferenceTransport').value;log(b.name+': assigned transport changed to '+b.transport+'.','Previous '+previous+' · planned assignment only');closeModal();render();toast('Assignment saved. No hardware changed.')}
function openAdHocTransport(){modal(`<h2>Add ad hoc transport</h2><p>Add a name for a nonstandard transport. It will be available for assignments without implying integrated schedule or health information.</p><label for="adHocName">Transport name</label><input id="adHocName" placeholder="e.g. Training relay"><div id="formError" class="error"></div><div class="form-foot"><button onclick="closeModal()">Back</button><button class="primary" onclick="saveAdHocTransport()">Add transport</button></div>`)}
function saveAdHocTransport(){const n=$('#adHocName').value.trim();if(!n)return $('#formError').textContent='Enter a transport name.';if(state.transportNames.some(x=>x.toLowerCase()===n.toLowerCase()))return $('#formError').textContent='That transport already exists.';state.transportNames.push(n);log('Ad hoc transport added: '+n+'.','No integrated outage schedule or health assurance');closeModal();render();toast('Transport added. Schedule coverage is unavailable.')}

render();

function timeControls(id,value,label){const [h,m]=value.split(':');const options=(n,current)=>Array.from({length:n},(_,i)=>String(i).padStart(2,'0')).map(v=>`<option ${v===current?'selected':''}>${v}</option>`).join('');return `<div class="time-row"><div><label for="${id}Hour">${label} hour · Zulu</label><select id="${id}Hour">${options(24,h)}</select></div><b>:</b><div><label for="${id}Minute">${label} minute</label><select id="${id}Minute">${options(60,m)}</select></div></div><p class="soft">24-hour Zulu · hour 00–23</p>`}
function readTime(id){return $('#'+id+'Hour').value+':'+$('#'+id+'Minute').value}
function scheduleText(c){return `${c.startDate} ${c.start} – ${c.endDate} ${c.end} Zulu`}
function prep(c){const d=new Date(c.startDate+'T'+c.start+':00Z');d.setUTCMinutes(d.getUTCMinutes()-10);const iso=d.toISOString();return {date:iso.slice(0,10),time:iso.slice(11,16)}}
